DROP TABLE IF EXISTS `exercise_day`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `exercise_day` (
  `exercise_day_id` int NOT NULL AUTO_INCREMENT,
  `is_completed` bit(1) DEFAULT NULL,
  `status` bit(1) DEFAULT NULL,
  `day_id` int DEFAULT NULL,
  `exercise_id` int DEFAULT NULL,
  `course_id` int DEFAULT NULL,
  PRIMARY KEY (`exercise_day_id`),
  KEY `day_id` (`day_id`),
  KEY `exercise_id` (`exercise_id`),
  KEY `idx_exercise_day_course` (`course_id`),
  CONSTRAINT `exercise_day_ibfk_1` FOREIGN KEY (`day_id`) REFERENCES `days` (`day_id`),
  CONSTRAINT `exercise_day_ibfk_2` FOREIGN KEY (`exercise_id`) REFERENCES `exercise` (`exercise_id`),
  CONSTRAINT `fk_exercise_day_course` FOREIGN KEY (`course_id`) REFERENCES `course` (`course_id`)
) ENGINE=InnoDB AUTO_INCREMENT=11043 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

