/*!50001 VIEW `course_rating_summary` AS select `c`.`course_id` AS `course_id`,`c`.`course_name` AS `course_name`,`c`.`average_rating` AS `average_rating`,count(`cr`.`rating_id`) AS `total_ratings`,(case when (count(`cr`.`rating_id`) >= 10) then 'Well Rated' when (count(`cr`.`rating_id`) >= 5) then 'Moderately Rated' when (count(`cr`.`rating_id`) > 0) then 'Few Ratings' else 'No Ratings' end) AS `rating_status` from (`course` `c` left join `course_ratings` `cr` on((`c`.`course_id` = `cr`.`course_id`))) group by `c`.`course_id`,`c`.`course_name`,`c`.`average_rating` order by `c`.`average_rating` desc,count(`cr`.`rating_id`) desc */;
